from lib import *
S = SS('j281')
steps = [
    step("经典 N+1(Hibernate 6.6.4 + PostgreSQL 16,1000 个作者、每人 5 本书):select a from Author a 一条查询 1 条 SQL,5.1 ms;随后逐个访问 a.books.size()(books 是懒加载集合)共 1001 条 SQL,201.5 ms(7 次中位数)——每个作者一条 select … from Book where author_id = ?。1 条查询看上去很便宜,逐个访问关联才是主要成本;数据库在本机,真实网络往返下差距更大。", t=tl(S(1)), done=lidx(S(1), '1 条查询 select a from Author a'), mark=lidx(S(1), '逐个访问 a.books.size()'), b=bars([['只查作者', 5.1, '5.1 ms / 1 条'], ['查作者 + 逐个访问 books', 201.5, '201.5 ms / 1001 条']], 202, done=[0, 1]), kv=KV([['select a from Author a', '1 条 SQL,5.1 ms'], ['再逐个访问 a.books.size()', '共 1001 条 SQL,201.5 ms']], ['再逐个访问 a.books.size()'])),
    step("@ManyToOne 默认是 EAGER,所以没有集合也会 N+1:em.find(Review, 1) 用 1 条 SQL(join 出作者,0.2 ms);JPQL select r from Review r 是 1001 条 SQL(1 条查评论,随后每个不同的作者各一条),35.9 ms;select r from Review r join fetch r.author 是 1 条 SQL,2.4 ms。find 会自动 join,而 JPQL 不会——同一个映射,两种读取方式的 SQL 数相差 1000 倍。把 @ManyToOne 改成 LAZY 并按需 join fetch。", t=tl(S(2)), done=lidx(S(2), 'em.find(Review, 1)'), mark=lidx(S(2), 'JPQL select r from Review r(默认 EAGER 的作者)', 'join fetch r.author'), kv=KV([['em.find(Review, 1)', '1 条 SQL(join)'], ['JPQL select r from Review r', '1001 条 SQL(EAGER 触发 N+1)'], ['join fetch r.author', '1 条 SQL,2.4 ms']], ['JPQL select r from Review r'])),
    step("几种修复方式(同样的工作:读出 1000 个作者并统计 5000 本书):基线 N+1:1001 条 SQL,183.3 ms;join fetch(select distinct a … join fetch a.books):1 条,9.7 ms;@BatchSize(size = 25):41 条(1 + ⌈1000 / 25⌉),31.5 ms;@Fetch(FetchMode.SUBSELECT):2 条,5.8 ms;EntityGraph(fetchgraph 提示):1 条,6.0 ms;DTO 投影(select new AuthorDto(a.id, a.name, count(b)) … group by):1 条,1.4 ms。DTO 只读取需要的列,最快;join fetch 与 EntityGraph 保留实体,SUBSELECT 适合不想改 JPQL 的场景。", t=tl(S(3)), done=lidx(S(3), '基线:N+1', 'join fetch(select distinct'), mark=lidx(S(3), '@BatchSize(size = 25)', 'SUBSELECT', 'EntityGraph', 'DTO 投影'), b=bars([['N+1 基线', 183.3, '183.3 ms / 1001 条'], ['join fetch', 9.7, '9.7 ms / 1 条'], ['@BatchSize(25)', 31.5, '31.5 ms / 41 条'], ['SUBSELECT', 5.8, '5.8 ms / 2 条'], ['EntityGraph', 6.0, '6.0 ms / 1 条'], ['DTO 投影', 1.4, '1.4 ms / 1 条']], 184, done=[0, 1, 2, 3, 4, 5]), kv=KV([['N+1', '1001 条 SQL'], ['join fetch / EntityGraph / DTO', '1 条 SQL'], ['SUBSELECT', '2 条 SQL'], ['@BatchSize(25)', '41 条 SQL']], ['join fetch / EntityGraph / DTO'])),
    step("同时抓取两个集合:两个 List 同时 join fetch 抛 IllegalArgumentException ← MultipleBagFetchException(cannot simultaneously fetch multiple bags: [Author.awards, Author.books])。改成 Set 就不报错,但会得到笛卡尔积:只 join fetch books(Set)数据库返回 5000 行、18.1 ms;同时 join fetch books 与 awards(各是 Set)返回 20000 行(每个作者 5 × 4 = 20 行)、50.7 ms——数据库读出的行数是两个集合大小的乘积。", t=tl(S(4)), done=lidx(S(4), '两个 List 同时 join fetch'), mark=lidx(S(4), 'Set join fetch books', 'Set 同时 join fetch books 与 awards'), b=bars([['join fetch books:行数', 5000, '5000 行'], ['join fetch books + awards:行数', 20000, '20000 行']], 20000, done=[0, 1]), kv=KV([['两个 List 同时 join fetch', 'MultipleBagFetchException'], ['两个 Set 同时 join fetch', '不报错,但 5 × 4 = 20 行 / 作者,共 20000 行']], ['两个 Set 同时 join fetch'])),
    step("分页 + 集合 join fetch:不带 fetch 的分页(setMaxResults(10))1 条 SQL,返回 10 个作者,3.9 ms,一级缓存里 10 个实体;带集合 join fetch 的分页同样返回 10 个作者,但日志警告 HHH90003004: firstResult/maxResults specified with collection fetch; applying in memory——SQL 里没有 limit,Hibernate 把整个结果集(1000 个作者 + 5000 本书)读进内存再取前 10 个,9.0 ms,一级缓存里有 6000 个实体。分页要在作者上做(先查主键再按 id in 抓取),不要带集合 fetch。", t=tl(S(5)), done=lidx(S(5), '不带 fetch 的分页查询'), mark=lidx(S(5), '带集合 join fetch 的分页查询', 'HHH90003004'), b=bars([['不带 fetch:一级缓存实体数', 10, '10'], ['带集合 fetch:一级缓存实体数', 6000, '6000']], 6000, done=[0, 1]), kv=KV([['不带 fetch 的 setMaxResults(10)', '10 个实体,SQL 带 limit'], ['带集合 join fetch', '警告 HHH90003004,读入 6000 个实体后在内存里分页']], ['带集合 join fetch'])),
]
A = mkartj('j281', 281, 'Java,JPA,Hibernate,N+1,join fetch,BatchSize,EntityGraph,PostgreSQL,真实验证,动画演示',
    '在 Hibernate 6.6.4 + 真实 PostgreSQL 上实测 JPA N+1:1000 个作者逐个访问 books 是 1001 条 SQL(201.5 ms);@ManyToOne 默认 EAGER 让 JPQL 也 N+1;join fetch / EntityGraph / DTO 为 1 条 SQL,@BatchSize 41 条,SUBSELECT 2 条;两个 List 同时 fetch 抛 MultipleBagFetchException,Set 得到 20000 行的笛卡尔积;带集合 fetch 的分页在内存里读入 6000 个实体。',
    'N+1 是 JPA 最常见的性能问题。这篇用 1000 个作者的真实数据,量出它从哪里来(懒加载集合与 EAGER 的 @ManyToOne)、几种修复方式的 SQL 数与耗时,以及 join fetch 带来的两个新问题:笛卡尔积与内存分页。',
    [('1001 条', '1000 个作者逐个访问 a.books.size() 发出的 SQL 数(join fetch / EntityGraph / DTO 都是 1 条)'), ('20000 行', '两个 Set 同时 join fetch(5 本书 × 4 个奖项 × 1000 个作者)数据库返回的行数(只 fetch books 是 5000 行)'), ('6000 个实体', '带集合 join fetch 的 setMaxResults(10) 在一级缓存里实际加载的实体数(警告 HHH90003004)')],
    [('经典 N+1', None), ('EAGER 的 @ManyToOne', None), ('修复方式对比', None), ('两个集合同时抓取', None), ('分页与集合 fetch', None)],
    steps, [ENV_J + '。Hibernate ORM 6.6.4.Final、PostgreSQL JDBC 42.7.4、本机 PostgreSQL 16.15(网络往返几乎为 0,真实环境差距更大);数据:1000 个作者 × 5 本书 × 4 个奖项 + 1000 条评论;耗时是 7 次中位数,SQL 数来自 Hibernate Statistics', '没有验证:Spring Data JPA 的 @EntityGraph 与 Specification、二级缓存对 N+1 的缓解、hibernate.default_batch_fetch_size 全局设置、@OneToOne 的 N+1、Hibernate 6.6 的 hibernate.query.fail_on_pagination_over_collection_fetch 开关、生产环境的慢查询日志与 N+1 检测工具'], 'JPA N+1 查询')
